	input, _ := reader.ReadString('\n')
	input = strings.TrimSpace(input)
	parts := strings.Split(input, " ")

	a, _ := strconv.Atoi(parts[0])
	b, _ := strconv.Atoi(parts[1])
	r, _ := strconv.Atoi(parts[2])

	digiGame(a, b, r)
}

